export function publicShell(content,{user=null,active='home'}={}){
 const cabinet=user?.role==='operator'?'operations':user?.role==='supplier'?'supply':'orders';
 return `<div class="marketing"><a class="skip-link" href="#" data-action="focus-main">К содержимому</a><header class="site-header"><a class="site-logo" href="#home" aria-label="Affsiwen — главная"><img src="assets/affsiwen-logo.svg" alt="Affsiwen"></a><nav aria-label="Основная навигация"><a href="#home" ${active==='home'?'aria-current="page"':''}>Продукт</a><a href="#catalog">Каталог Agents</a><a href="#start/supplier" ${active==='supplier'?'aria-current="page"':''}>Партнёрам</a></nav><div class="actions">${user?`<a class="secondary" href="#${cabinet}">Мой кабинет</a>`:'<a class="site-login" href="#login">Войти</a>'}<a class="primary" href="#start/buyer">Начать с задачи</a></div></header><div class="preview-ribbon">Демоверсия платформы <span>Синтетические результаты · без реальных списаний</span></div><main class="site-main" id="page-content" tabindex="-1">${content}</main><footer class="site-footer"><a class="site-logo" href="#home"><img src="assets/affsiwen-logo.svg" alt="Affsiwen"></a><div><strong>Affsiwen · Luxembourg</strong><span>Данные для продаж, маркетинга и исследований.</span></div><nav aria-label="Дополнительная навигация"><a href="#methodology">Как отбираем Agents</a><a href="#start/supplier">Стать партнёром</a><a href="#start/operator">Для команды</a></nav></footer></div>`;
}
function resultPreview(key){const x=examples[key]||examples.companies;return `<div class="result-demo"><div class="demo-top"><span class="sample-label">ПРИМЕР РЕЗУЛЬТАТА</span><span class="sample-label">CSV / JSON</span></div><div class="example-tabs" role="group" aria-label="Примеры задач">${Object.entries(examples).map(([id,v])=>`<button data-action="landing-example" data-value="${id}" aria-pressed="${id===key}">${v.label}</button>`).join('')}</div><div class="demo-prompt"><span>01 / ЗАДАЧА</span><p>«${esc(x.query)}»</p></div><div class="demo-agent"><span class="agent-symbol">A</span><div><small>02 / AGENT AFFSIWEN</small><strong>${x.agent}</strong></div><span class="file-chip">Таблица</span></div><div class="sample-table"><table><caption>03 / ПРИМЕР ВЫДАЧИ · ДАННЫЕ ВЫМЫШЛЕНЫ</caption><thead><tr>${x.columns.map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${x.rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="sample-note">${x.note}</p><button class="demo-link" data-action="landing-try" data-value="${key}">Разобрать похожую задачу</button></div>`;}
function journeySteps(role){return `<ol class="journey-steps">${journeys[role].steps.map(([title,text],i)=>`<li><span class="step-no">0${i+1}</span><h3>${title}</h3><p>${text}</p></li>`).join('')}</ol>`;}
export function landing({example='companies',role='buyer'}={}){if(!['buyer','supplier'].includes(role))role='buyer';const j=journeys[role];return `<section class="landing-hero"><div class="landing-intro"><div class="overline">ДАННЫЕ ДЛЯ ВАШЕЙ СЛЕДУЮЩЕЙ ЗАДАЧИ</div><h1>От бизнес-задачи<br><em>к готовым данным.</em></h1><p>Найдите компании для продаж, изучите рекламу конкурентов или соберите контент для исследования. Опишите, что вам нужно — Affsiwen поможет выбрать Agent и получить результат в таблице.</p><div class="hero-cta"><a class="primary" href="#start/buyer">Подобрать решение</a><a class="secondary" href="#catalog">Посмотреть каталог</a></div><div class="hero-caption">Agent — готовый сценарий сбора данных.<br>Задание, статус и результат — в вашем кабинете.</div></div>${resultPreview(example)}</section><section class="value-strip" aria-label="Что включает продукт"><div><b>Понятная задача</b><span>Объясните своими словами</span></div><div><b>Конкретная выдача</b><span>Состав данных до заказа</span></div><div><b>Контроль у вас</b><span>Запуск после подтверждения</span></div></section><section class="site-section"><div class="section-heading"><div><div class="overline">ЧТО МОЖНО СДЕЛАТЬ</div><h2>Выбирайте результат,<br>который нужен бизнесу.</h2></div><p>Каждый Agent решает конкретную задачу. В карточке — параметры, состав выдачи и ограничения.</p></div><div class="usecase-grid">${Object.entries(examples).map(([id,x],i)=>`<article class="usecase"><div class="usecase-top"><span class="overline">${x.tag}</span><span class="usecase-no">0${i+1}</span></div><h3>${x.title}</h3><p>${x.result}</p><a href="#product/${x.product}">Открыть Agent</a></article>`).join('')}</div></section><section class="site-section journey-section"><div class="section-heading"><div><div class="overline">КАК ВСЁ УСТРОЕНО</div><h2>Свой путь для каждой роли.</h2></div><div class="role-tabs" role="group" aria-label="Ваш сценарий">${['buyer','supplier'].map(r=>`<button data-action="landing-role" data-value="${r}" aria-pressed="${role===r}">${journeys[r].label}</button>`).join('')}</div></div><div class="journey-heading"><h3>${j.title}</h3><a class="secondary" href="#start/${role}">${role==='buyer'?'Начать подбор':'Стать партнёром'}</a></div>${journeySteps(role)}</section><section class="responsibility"><div><div class="overline">ЧТО ВЫ ПОКУПАЕТЕ</div><h2>Один сбор.<br>Понятный результат.</h2><p>Вы заказываете сбор данных по выбранным параметрам. Стоимость и ограничения видны до подтверждения.</p><a class="primary" href="#start/buyer">Разобрать мою задачу</a></div><div class="deliverable-list"><article><span>01</span><div><h3>Данные в рабочем формате</h3><p>Таблица в кабинете, CSV для работы в таблицах и JSON для интеграций.</p></div></article><article><span>02</span><div><h3>История и повторный сбор</h3><p>Сохранённый заказ и параметры, с которыми можно вернуться к задаче.</p></div></article><article><span>03</span><div><h3>Проверка спорного результата</h3><p>Обращение по заказу, если выдачу нужно проверить. Данные сами по себе не гарантируют продажи.</p></div></article></div></section><section class="site-section faq-section"><div><div class="overline">ПЕРЕД СТАРТОМ</div><h2>Коротко<br>о главном.</h2></div><div class="faq-list">${[
 ['Мне нужно разбираться в сборе данных?','Нет. Опишите, что ищете и для чего. Помощник уточнит параметры и предложит подходящий Agent. Если вы уже знаете нужный продукт, выберите его в каталоге.'],
 ['Что происходит после заказа?','После подтверждения оплаты заказ переходит в исполнение. Статус и результат появляются в кабинете. На этом стенде оплата демонстрационная, а выдача состоит из синтетических примеров.'],
 ['Сколько стоит результат?','Цена указана на странице выбранного Agent до создания заказа. Текущие цены сценарные: коммерческий прайс будет утверждён после проверки фактической себестоимости.'],
 ['Подбор уже работает на AI?','В этой демоверсии работает ограниченный сценарий диалога. Интеграция с LLM подготовлена, но ещё не подключена. Она будет подбирать только из доступных Agents; решение о заказе остаётся за вами.'],
 ['Можно предложить свой продукт?','Да. Подготовьте описание, пример входных параметров и ожидаемой выдачи. После регистрации партнёра заявка поступит на проверку. Коммерческие условия согласуются отдельно; заявка не обещает продажи или выплаты.']
 ].map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</div></section><section class="closing-cta"><div><div class="overline">НАЧНЁМ С ВАШЕЙ ЗАДАЧИ</div><h2>Какие данные нужны вам?</h2><p>Поможем определить результат до того, как вы создадите заказ.</p></div><div class="hero-cta"><a class="primary" href="#start/buyer">Я ищу решение</a><a class="secondary" href="#start/supplier">Я предлагаю продукт</a></div></section>`;}
export function roleWelcome(role,{user,health}={}){const j=journeys[role];if(!j)return '<h1>Сценарий не найден</h1>';const allowed=role!=='operator'||user?.role==='operator';return `<section class="role-hero"><a class="quiet-link" href="#home">На главную</a><div class="overline">${j.tag}</div><h1>${j.title}</h1><p>${j.intro}</p><div class="hero-cta"><a class="primary" href="${allowed?j.target:'#login/operator'}">${allowed?j.cta:'Войти в аккаунт команды'}</a>${role==='buyer'?'<a class="secondary" href="#catalog">Выбрать в каталоге</a>':role==='supplier'?'<a class="secondary" href="#supply">Мои заявки</a>':''}</div>${role==='operator'?'<p class="role-note">Эта страница объясняет процесс. Она не предоставляет доступ оператора.</p>':''}</section><section class="role-route">${journeySteps(role)}</section>${role==='buyer'?`<section class="role-detail"><div><div class="overline">ДЛЯ ПЕРВОГО ПОДБОРА</div><h2>Достаточно рассказать,<br>что вы хотите узнать.</h2><p>Не нужно заранее выбирать инструмент. Начните, например, с одной из этих задач.</p></div><div class="role-examples">${Object.entries(examples).map(([id,x])=>`<button data-action="landing-try" data-value="${id}">${x.query}</button>`).join('')}</div></section>`:role==='supplier'?`<section class="role-detail"><div><div class="overline">ЧТО НУЖНО ПОДГОТОВИТЬ</div><h2>Покажите пользу<br>вашего продукта.</h2><p>Ваша заявка видна вам и команде Affsiwen. До решения она не появляется в каталоге покупателей.</p></div><ul class="role-checklist"><li>Задача и аудитория продукта</li><li>Пример входных параметров и поля результата</li><li>Идентификатор интеграции без секретных ключей</li><li>Ограничения и условия использования</li></ul></section>`:`<section class="role-detail"><div><div class="overline">РАБОЧИЕ РАЗДЕЛЫ</div><h2>От проверки<br>до выдачи.</h2><p>Коммерческий запуск требует проверки каждого продукта и подключений. В демо можно проверить интерфейс и последовательность работы.</p></div><div class="operator-shortcuts">${[['sourcing','Отбор продуктов','Кандидаты, статусы и цены'],['launch','Готовность к запуску','Подключения и коммерческие проверки'],['operations','Операции','Очередь и проблемные заказы'],['analytics','Экономика','Оплаты, выдача и сверка расходов']].map(([route,title,desc])=>`<a href="${allowed?'#'+route:'#login/operator'}"><strong>${title}</strong><span>${desc}</span></a>`).join('')}</div></section>`}<section class="role-bottom"><p>${role==='supplier'?'Условия, права и стоимость проверяются до коммерческого запуска. Фиксированный процент выплат не обещаем.':role==='buyer'?'Сначала параметры и состав результата. Затем ваше подтверждение.':'Доступ к рабочим разделам проверяется на сервере.'}</p><a class="primary" href="${allowed?j.target:'#login/operator'}">${allowed?j.cta:'Войти'}</a></section>`;}
